using namespace std;

// Iterative implementation
int getGCD(int a, int b) {
    while (a > 0 && b > 0) {
        if (a > b) {
            a = a % b;
        }
        else {
            b = b % a;
        }
    }
    if (a == 0) {
        return b;
    }
    return a;
}

int GcdOfArray(vector<int>& arr) {
    int gcd = arr[0];
    for (int i = 1; i < arr.size(); i++) {
        gcd = getGCD(gcd, arr[i]);
    }
    return gcd;
}

int main() {
    vector<int> arr = { 2, 4, 6, 8 };
    cout << GcdOfArray(arr) << "\n";
    return 0;
}


